    /// ```html,expect_diagnostic
    /// <h1><span aria-hidden="true">content</span></h1>
    /// ```
    ///
    /// ### Valid
    ///
    /// ```html
    /// <h1>heading</h1>
    /// ```
    ///
    /// ```html
    /// <h1><span>heading</span></h1>
    /// ```
    ///
    /// ```html
    /// <h1><span aria-hidden="true"></span>visible content</h1>
    /// ```
    ///
