impl Rule for UseHeadingContent {
    type Query = Ast<AnyHtmlElement>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = UseHeadingContentOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let node = ctx.query();

        // Check if the element is a heading (h1-h6).
        // In HTML files, tag names are case-insensitive.
        // In component frameworks (Vue, Svelte, Astro), only lowercase is checked;
        // PascalCase names are assumed to be custom components.
        let element_name = node.name()?;
        let source_type = ctx.source_type::<HtmlFileSource>();
        let is_heading = if source_type.is_html() {
            is_heading_name(&element_name.text().to_ascii_lowercase())
        } else {
            is_heading_name(element_name.text())
        };
        if !is_heading {
            return None;
        }

        // `aria-hidden` on the heading itself hides all of its content from
        // assistive technologies. This takes priority over any accessible name.
        if get_truthy_aria_hidden_attribute(node).is_some() {
            return Some(());
        }

        // An accessible name provided directly on the heading is enough.
        if has_accessible_name(node) {
            return None;
        }

        // Self-closing headings (void-style) have no content.
        let Some(html_element) = node.as_html_element() else {
            return Some(());
